import * as THREE from './vendor/three.module.js';
export function disposeMarker(root){root.traverse(m=>{m.geometry?.dispose();for(const mat of Array.isArray(m.material)?m.material:m.material?[m.material]:[])mat.dispose();});}
function line(points,color){const m=new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(points.map(p=>new THREE.Vector3(...p))),new THREE.LineBasicMaterial({color,depthTest:false,transparent:true,opacity:.8}));m.renderOrder=8;return m;}
export function createMarker(kind,id){const root=new THREE.Group(),color=kind==='wind'?'#80c5ee':kind==='suction'?'#be9bef':kind==='explosion'?'#f1ac65':'#d4dbe5';root.userData={pointKind:kind==='wind'||kind==='suction'?'field':kind,pointId:id};
 if(kind==='wind'){const g=new THREE.BoxGeometry(1,1,1);root.add(new THREE.LineSegments(new THREE.EdgesGeometry(g),new THREE.LineBasicMaterial({color})));g.dispose();const holder=new THREE.Group();holder.position.z=-.45;const arrow=new THREE.ArrowHelper(new THREE.Vector3(0,0,1),new THREE.Vector3(),.9,color,.14,.09);holder.add(arrow);root.add(holder);root.userData.directionArrow=arrow;root.userData.directionRoot=holder;}
 else if(kind==='suction'){const points=[];for(let i=0;i<48;i++){const a=i*Math.PI/24,b=(i+1)*Math.PI/24;points.push([Math.cos(a)*.5,Math.sin(a)*.5,1],[Math.cos(b)*.5,Math.sin(b)*.5,1]);if(i%12===0)points.push([0,0,0],[Math.cos(a)*.5,Math.sin(a)*.5,1]);}root.add(line(points,color));}
 else if(kind==='explosion'){const sphere=new THREE.Mesh(new THREE.IcosahedronGeometry(.13,0),new THREE.MeshBasicMaterial({color,wireframe:true,depthTest:false}));root.add(sphere);const p=[];for(const x of [-1,1])for(const y of [-1,1])for(const z of [-1,1])p.push([x*.11,y*.11,z*.11],[x*.25,y*.25,z*.25]);root.add(line(p,color));}
 else if(kind==='hinge'){const ring=new THREE.Mesh(new THREE.TorusGeometry(.2,.025,6,24),new THREE.MeshBasicMaterial({color,depthTest:false}));root.add(ring,new THREE.ArrowHelper(new THREE.Vector3(0,0,1),new THREE.Vector3(0,0,-.3),.6,color,.1,.07));}
 else{const g=new THREE.BoxGeometry(.16,.16,.16);root.add(new THREE.LineSegments(new THREE.EdgesGeometry(g),new THREE.LineBasicMaterial({color,depthTest:false})));g.dispose();root.add(line([[-.22,0,0],[.22,0,0],[0,-.22,0],[0,.22,0],[0,0,-.22],[0,0,.22]],color));}
 if(kind==='wind'||kind==='suction'){const dot=new THREE.Mesh(new THREE.SphereGeometry(.065,16,10),new THREE.MeshBasicMaterial({color,depthTest:false,transparent:true,opacity:.9}));root.add(dot);root.userData.centerDot=dot;}
 const pick=new THREE.Mesh(new THREE.SphereGeometry(kind==='wind'||kind==='suction'?.18:.2,10,8),new THREE.MeshBasicMaterial({color,transparent:true,opacity:0,depthWrite:false,visible:false}));root.add(pick);root.traverse(m=>{m.userData={...root.userData};m.renderOrder=8;});return root;}

// Scale the field volume, while keeping its direction arrow and head in world units.
export function setMarkerSize(root,size){root.scale.fromArray(size);root.userData.centerDot?.scale.set(1/size[0],1/size[1],1/size[2]);const arrow=root.userData.directionArrow;if(arrow){root.userData.directionRoot.scale.set(1/size[0],1/size[1],1/size[2]);arrow.setLength(.9*size[2],.14,.09);}}
